import{_ as n,o as h,c as a,ag as r}from"./chunks/framework.CrQUFeyH.js";const g=JSON.parse('{"title":"Hỏi đáp lớp Thiền Quán Niệm Tứ Đại","description":"","frontmatter":{"title":"Hỏi đáp lớp Thiền Quán Niệm Tứ Đại"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),e={name:"index.md"};function i(l,t,u,o,s,c){return h(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="hoi-đap-lop-thien-quan-niem-tu-đai" tabindex="-1">Hỏi đáp lớp Thiền Quán Niệm Tứ Đại <a class="header-anchor" href="#hoi-đap-lop-thien-quan-niem-tu-đai" aria-label="Permalink to &quot;Hỏi đáp lớp Thiền Quán Niệm Tứ Đại&quot;">​</a></h1><h2 id="buoi-so-1" tabindex="-1">Buổi số 1 <a class="header-anchor" href="#buoi-so-1" aria-label="Permalink to &quot;Buổi số 1&quot;">​</a></h2><p>Không có câu hỏi</p><h2 id="buoi-so-2" tabindex="-1">Buổi số 2 <a class="header-anchor" href="#buoi-so-2" aria-label="Permalink to &quot;Buổi số 2&quot;">​</a></h2><ul><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=5396" target="_blank" rel="noreferrer">Làm sao cảm nhận được tính đẩy?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=5564" target="_blank" rel="noreferrer">Chuyển từ chân sang bàn tay cần hướng tâm, đó có phải là tưởng không?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=5700" target="_blank" rel="noreferrer">Đau ở bắp chân, làm sao tập trung được tính đẩy ở đó?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6023" target="_blank" rel="noreferrer">Mạch đập vùng thái dương có phải tính đẩy?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6077" target="_blank" rel="noreferrer">Khi nối các phần với nhau có phải là cảm nhận tổng thể?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6150" target="_blank" rel="noreferrer">Nhìn thấy tính đẩy hay cảm nhận tính đẩy?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6414" target="_blank" rel="noreferrer">Có phải giữ nguyên tư thế từ đầu đến cuối?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6595" target="_blank" rel="noreferrer">Khi quán các bộ phận đối xứng (tay, chân), quán 1 bên hay 2 bên cùng lúc?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=6805" target="_blank" rel="noreferrer">Tính đẩy liên quan yếu tố gió: gió bên trong cơ thể hay gió bên ngoài tác động?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=7004" target="_blank" rel="noreferrer">Duỗi chân được không? Quán chỗ nào cảm nhận rõ trước hay phải theo trình tự?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=7205" target="_blank" rel="noreferrer">Đau vai trái, cần điều chỉnh thế nào?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=7389" target="_blank" rel="noreferrer">Cảm nhận hơi thở một bên lỗ mũi là như thế nào?</a></li><li><a href="https://youtu.be/10MdsOWwKZU&amp;t=7630" target="_blank" rel="noreferrer">Làm gì khi cảm nhận nặng ở vùng ngực khi quan sát hơi thở?</a></li></ul><h2 id="buoi-so-3" tabindex="-1">Buổi số 3 <a class="header-anchor" href="#buoi-so-3" aria-label="Permalink to &quot;Buổi số 3&quot;">​</a></h2><ul><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4233" target="_blank" rel="noreferrer">Chỉ tập trung vào phần có tính đẩy rõ nhất (bụng phồng xẹp) có được không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4297" target="_blank" rel="noreferrer">Khi quán tính đẩy bị sao nhãng, nên bắt đầu từ đầu hay tiếp tục ở chỗ sao nhãng?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4438" target="_blank" rel="noreferrer">Quan sát nhanh qua yếu tố đã rõ, dành thời gian quan sát yếu tố chưa rõ có được không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4679" target="_blank" rel="noreferrer">Thân trên chuyển động khi ngồi thiền có phải là tính đẩy?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4825" target="_blank" rel="noreferrer">Từng phần cơ thể như bị giãn ra khi đưa sự quan sát đến đó, có bình thường không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=4926" target="_blank" rel="noreferrer">Quán niệm hơi thở trước khi chuyển sang thiền Tứ Đại được không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=5050" target="_blank" rel="noreferrer">Bôi dầu để cảm nhận rõ hơn yếu tố gió ở mũi có được không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=5831" target="_blank" rel="noreferrer">Quan sát tính rắn là như thế nào?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=6046" target="_blank" rel="noreferrer">Quan sát từng đặc tính ở các vùng hay nhiều đặc tính tại cùng một vùng?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=6180" target="_blank" rel="noreferrer">Tính rắn bên trái rõ hơn bên phải nên tập trung bên nào? Làm sao quan sát liên tục tính đẩy mà không bị sao nhãng bởi tính rắn?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=6630" target="_blank" rel="noreferrer">Làm sao để nhận biết tính rắn? Làm sao biết mình đã nhận biết đúng?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7065" target="_blank" rel="noreferrer">Cách khắc phục tình trạng buồn ngủ, mơ màng khi thiền?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7195" target="_blank" rel="noreferrer">Mệt mỏi có phải do tập trung quá?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7365" target="_blank" rel="noreferrer">Không thấy hơi thở khi quan sát tính đẩy có sao không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7530" target="_blank" rel="noreferrer">Quan sát tính đẩy theo trình tự từ ngực tới vùng tim tới bụng, ruột, dạ dày có đúng không?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7669" target="_blank" rel="noreferrer">Tại sao quan sát tính rắn lại nhanh và dễ hơn tính đẩy?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=7840" target="_blank" rel="noreferrer">Có nên suy nghĩ về mối quan hệ giữa các đại khi hành thiền?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=8080" target="_blank" rel="noreferrer">Một số phần khó cảm nhận đặc tính hơn các phần khác phải làm sao? Cảm nhận tính rắn khi đang quan sát tính đẩy có phải do căng thẳng?</a></li><li><a href="https://youtu.be/VvLs2q9WmmM&amp;t=8498" target="_blank" rel="noreferrer">Phân biệt luồng khí vào ra ở mũi (Anapana) với tính đẩy của gió</a></li></ul><h2 id="buoi-so-4" tabindex="-1">Buổi số 4 <a class="header-anchor" href="#buoi-so-4" aria-label="Permalink to &quot;Buổi số 4&quot;">​</a></h2><ul><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=2261" target="_blank" rel="noreferrer">Hơi thở ra vào không phải là yếu tố gió</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=2558" target="_blank" rel="noreferrer">Có cần xác định trước ngồi thiền trong bao lâu không?</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=2687" target="_blank" rel="noreferrer">Cảm giác có luồng điện chạy trên đầu có sao không?</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=3080" target="_blank" rel="noreferrer">Khó phân định sự đẩy của gió với hơi thở trong lồng ngực</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=3320" target="_blank" rel="noreferrer">Mất tập trung khi chuyển sự chú ý từ ngực xuống bụng</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=3780" target="_blank" rel="noreferrer">Quan sát hơi thở trước rồi quan sát tính đẩy của yếu tố gió? Quét yếu tố Đất từng ngón tay/chân hay cả bàn tay/chân?</a></li><li><a href="https://youtu.be/DJsXGZf-qQU&amp;t=4050" target="_blank" rel="noreferrer">Cảm nhận như có sâu bọ ở trên đầu lúc quan sát có sao không?</a></li></ul><h2 id="buoi-so-5" tabindex="-1">Buổi số 5 <a class="header-anchor" href="#buoi-so-5" aria-label="Permalink to &quot;Buổi số 5&quot;">​</a></h2><ul><li><a href="https://youtu.be/3S6WBKTx1Oo&amp;t=3132" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Yến Thanh</a></li><li><a href="https://youtu.be/3S6WBKTx1Oo&amp;t=3426" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Tín Duyên</a></li><li><a href="https://youtu.be/3S6WBKTx1Oo&amp;t=3743" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Phương Tô</a></li><li><a href="https://youtu.be/3S6WBKTx1Oo&amp;t=4368" target="_blank" rel="noreferrer">Sự lưu thông của máu có phải yếu tố gió? Sức nặng của tay trên đùi, chân trên sàn có phải yếu tố đất?</a></li><li><a href="https://youtu.be/3S6WBKTx1Oo&amp;t=5084" target="_blank" rel="noreferrer">Bị cúi đầu về phía trước có cần chỉnh lại tư thế?</a></li></ul><h2 id="buoi-so-6" tabindex="-1">Buổi số 6 <a class="header-anchor" href="#buoi-so-6" aria-label="Permalink to &quot;Buổi số 6&quot;">​</a></h2><ul><li><p><a href="https://www.youtube.com/watch?v=NMvJ5So-5QQ&amp;t=312s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Diệu Tịnh</a></p><ul><li>Bị sao lãng thất niệm, phải quay lại từ đầu hay tiếp tục từ chỗ bị sao lãng</li><li>Khi quan sát, làm sao biết mình đang hành đúng mà không phải là phát triển các đặc tính do nỗ lực quá mức?</li><li>Khi quan sát đặc tính rắn, có quan sát phần cơ thịt mềm không hay chỉ quan sát phần xương?</li><li>Khi có cơn đau nên quan sát như thế nào?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=NMvJ5So-5QQ&amp;t=1202s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Vũ Thanh Thảo</a></p><ul><li>Khi thất niệm có nên đổi tư thế cho tỉnh táo, định tâm lại?</li><li>Không cảm nhận được tính đẩy từ đùi trở xuống phải làm sao?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=NMvJ5So-5QQ&amp;t=1690s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Đức Bình</a></p><ul><li>Khi thực hành thiền hơi thở, làm sao không bị phân tâm bởi âm thanh, hình ảnh loáng thoáng xuất hiện?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=NMvJ5So-5QQ&amp;t=1980s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Thúy Vi</a></p><ul><li>Đau bụng khi ngồi thiền, cơn đau lên xuống có phải sự đẩy của yếu tố gió?</li><li>Quán chiếu cơn đau là thọ khổ, biến đổi sanh diệt của yếu tố gió và đất có đúng không?</li><li>Khi quán hơi thở, có cơn gió mạnh hất vào mặt, đẩy người ngửa ra đằng sau cần ghi nhận thế nào?</li></ul></li></ul><h2 id="buoi-so-7" tabindex="-1">Buổi số 7 <a class="header-anchor" href="#buoi-so-7" aria-label="Permalink to &quot;Buổi số 7&quot;">​</a></h2><ul><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=3198s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Kim Võ</a></p></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=3762s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Nguyễn Văn Long</a></p><ul><li>Quan sát tính đẩy từ ngực xuống bụng rồi lên đầu. Khi quan sát trên đầu có tác ý đẩy lên đỉnh đầu, cảm thấy giật giật trên đỉnh đầu một lúc. Như vậy có đúng không?</li><li>Quan sát tính đẩy từ trong ra ngoài hay dọc cơ thể? Quan sát thấy ở ngực và bụng có tính đấy ngang, ở tay chân có tính đẩy dọc, có đúng không?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=4740s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Tuyết Nguyễn</a></p></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=5959s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Lê Quang Anh</a></p><ul><li>Làm thể nào để lấy lại sự tập trung khi bị phóng tâm?</li><li>Dùng ghế hỗ trợ khi ngồi thiền có được không?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=6608s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Doan Dong</a></p><ul><li>Có cần đạt các tầng thiền trước khi chuyển sang Vipassanā không?</li><li>Có nên lo ngại rằng thiền định nhiều sẽ tạo ra sự dính mắc trong trạng thái tĩnh lặng hoàn hỉ mà không thể chuyển sang thiền tuệ (Vipassanā) không?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=6873s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Nguyen Ha</a></p><ul><li>Thấy mệt mỏi, khó thở khi quan sát hơi thở phải làm sao?</li></ul></li><li><p><a href="https://www.youtube.com/watch?v=-7se8SdV9Gc&amp;t=7115s" target="_blank" rel="noreferrer">Làm gì khi nuốt nước miếng khi hành thiền?</a></p></li></ul><h2 id="buoi-so-8" tabindex="-1">Buổi số 8 <a class="header-anchor" href="#buoi-so-8" aria-label="Permalink to &quot;Buổi số 8&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=280s" target="_blank" rel="noreferrer">Điều chỉnh tư thế do đau chân</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=533s" target="_blank" rel="noreferrer">Phải làm gì khi hơi thở trở nên rất nhẹ?</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=718s" target="_blank" rel="noreferrer">Cảm giác nóng bức và toát mồ hôi khi thiền cần làm gì?</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=1022s" target="_blank" rel="noreferrer">Mệt mỏi, toát mồ hôi khi quan sát hơi thở?</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=1448s" target="_blank" rel="noreferrer">Tư thế ngồi với bệnh giãn tĩnh mạch chân</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=1650s" target="_blank" rel="noreferrer">Nghe thấy tiếng nói thì thầm khi hành thiền</a></li><li><a href="https://www.youtube.com/watch?v=5hao-0l7uaE&amp;t=2430s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Mighty Fuku</a></li></ul><h2 id="buoi-so-9" tabindex="-1">Buổi số 9 <a class="header-anchor" href="#buoi-so-9" aria-label="Permalink to &quot;Buổi số 9&quot;">​</a></h2><p>Không có câu hỏi</p><h2 id="buoi-so-10" tabindex="-1">Buổi số 10 <a class="header-anchor" href="#buoi-so-10" aria-label="Permalink to &quot;Buổi số 10&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=3072s" target="_blank" rel="noreferrer">Thiền hành trên bãi biển, cần chú ý gì?</a></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=3220s" target="_blank" rel="noreferrer">Thiền hành trong công viên có cần quay đầu hay đi thẳng?</a></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=3435s" target="_blank" rel="noreferrer">Có lộ trình tăng dần số bước chân không?</a></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=3575s" target="_blank" rel="noreferrer">Cần làm gì khi có suy nghĩ hoặc cảm thọ khởi sinh trong lúc đang đi kinh hành?</a></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=3795s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Kim Võ</a><ul><li>Nhận biết cảm giác ấm/mát của hơi thở có đúng không?</li><li>Nhận biết cảm giác ấm/mát của hơi thở có đúng không?</li><li>Cách giữ tâm bớt xao nhãng trong các hoạt động hàng ngày</li></ul></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=4380s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Phương Tô</a><ul><li>Phân biệt giữa quan sát hơi thở (Anapanasati) và sự phồng xẹp ở bụng.</li><li>Cách khắc phục tình trạng buồn ngủ và trùn lưng khi thiền.</li></ul></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=4948s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Uyên Ngô</a><ul><li>Lời khuyên thiền tập cho người có bệnh lý khó thở hoặc hay bị hụt hơi</li></ul></li><li><a href="https://www.youtube.com/watch?v=7pcmlQ4dqqs&amp;t=5428s" target="_blank" rel="noreferrer">Trình pháp Đạo hữu Tama Le</a><ul><li>Sự khác biệt giữa sự tập trung khi học tập/làm việc và sự định tâm trong thiền</li></ul></li></ul>',21)])])}const m=n(e,[["render",i]]);export{g as __pageData,m as default};
